      validateMessage({type: 'list_conversations', limit: 201}),
      validateMessage({type: 'list_conversations', limit: 1.5}),
      validateMessage({type: 'list_conversations', limit: '10'}),
      validateMessage({type: 'list_conversations', before: 'not a date'}),
    ];

    expect(results).toEqual([
      {
        valid: true,
        data: {
          type: 'list_conversations',
          limit: 10,
          before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
        },
      },
      ...Array(4).fill({valid: false, error: expect.stringContaining('limit')}),
      {valid: false, error: expect.stringContaining('before')},
    ]);
  });

  it('rejects a cursor session id longer than 128 characters', () => {
    expect(
      validateMessage({
        type: 'list_conversations',
        before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      })
    ).toEqual({valid: false, error: expect.stringContaining('sessionId')});
  });
